def _flatten_dict_for_synthesis(d, prefix=""):
    out = {}
    if isinstance(d, dict):
        for k, v in d.items():
            key = f"{prefix}.{k}" if prefix else str(k)
            if isinstance(v, dict):
                out.update(_flatten_dict_for_synthesis(v, key))
            else:
                out[key] = v
    return out

